const VALID_TYPES = new Set([
  "charge.success",
  "charge.failed",
  "charge.abandoned",
  "refund.processed",
]);

const TERMINAL_CHARGE_STATUSES = new Set([
  "success",
  "partially_refunded",
  "refunded",
  "amount_mismatch",
]);

const hasOwn = Object.prototype.hasOwnProperty;

export function createLedger({ expectedAmounts = {} } = {}) {
  const entries = new Map();
  const handledIds = new Set();

  function createEntry(reference) {
    const hasExpectedAmount =
      expectedAmounts != null &&
      hasOwn.call(expectedAmounts, reference);

    const expectedAmount = hasExpectedAmount
      ? expectedAmounts[reference]
      : null;

    const entry = {
      reference,
      status: "pending",
      amountKobo: expectedAmount,
      refundedKobo: 0,
      deferredRefunds: [],
      hasExpectedAmount,
      expectedAmount,
    };

    entries.set(reference, entry);
    return entry;
  }

  function applyRefund(entry, amountKobo) {
    if (entry.status === "refunded") {
      return false;
    }

    const newTotal = entry.refundedKobo + amountKobo;

    if (newTotal > entry.amountKobo) {
      return false;
    }

    entry.refundedKobo = newTotal;
    entry.status =
      newTotal === entry.amountKobo
        ? "refunded"
        : "partially_refunded";

    return true;
  }

  function applyDeferredRefunds(entry) {
    for (const amountKobo of entry.deferredRefunds) {
      applyRefund(entry, amountKobo);
    }

    entry.deferredRefunds.length = 0;
  }

  function handle(event) {
    if (event == null || !VALID_TYPES.has(event.type)) {
      return {
        applied: false,
        reason: "unknown-type",
        status: null,
      };
    }

    const { id, reference, type } = event;
    const currentEntry = entries.get(reference);

    if (handledIds.has(id)) {
      return {
        applied: false,
        reason: "duplicate",
        status: currentEntry ? currentEntry.status : null,
      };
    }

    let amountKobo;

    if (type === "charge.success" || type === "refund.processed") {
      amountKobo = event.amountKobo;

      if (!Number.isInteger(amountKobo) || amountKobo <= 0) {
        return {
          applied: false,
          reason: "invalid-amount",
          status: currentEntry ? currentEntry.status : null,
        };
      }
    }

    handledIds.add(id);

    const entry = currentEntry || createEntry(reference);

    if (type !== "refund.processed") {
      if (TERMINAL_CHARGE_STATUSES.has(entry.status)) {
        return {
          applied: false,
          reason: "terminal",
          status: entry.status,
        };
      }

      if (type === "charge.failed") {
        if (entry.status === "failed") {
          return {
            applied: false,
            reason: "stale",
            status: entry.status,
          };
        }

        entry.status = "failed";

        return {
          applied: true,
          reason: null,
          status: entry.status,
        };
      }

      if (type === "charge.abandoned") {
        if (entry.status !== "pending") {
          return {
            applied: false,
            reason: "stale",
            status: entry.status,
          };
        }

        entry.status = "abandoned";

        return {
          applied: true,
          reason: null,
          status: entry.status,
        };
      }

      if (
        entry.hasExpectedAmount &&
        amountKobo !== entry.expectedAmount
      ) {
        entry.status = "amount_mismatch";
        entry.deferredRefunds.length = 0;

        return {
          applied: true,
          reason: "amount-mismatch",
          status: entry.status,
        };
      }

      entry.amountKobo = entry.hasExpectedAmount
        ? entry.expectedAmount
        : amountKobo;
      entry.status = "success";

      applyDeferredRefunds(entry);

      return {
        applied: true,
        reason: null,
        status: entry.status,
      };
    }

    if (
      entry.status === "success" ||
      entry.status === "partially_refunded"
    ) {
      if (!applyRefund(entry, amountKobo)) {
        return {
          applied: false,
          reason: "over-refund",
          status: entry.status,
        };
      }

      return {
        applied: true,
        reason: null,
        status: entry.status,
      };
    }

    if (entry.status === "refunded") {
      return {
        applied: false,
        reason: "over-refund",
        status: entry.status,
      };
    }

    if (entry.status === "amount_mismatch") {
      return {
        applied: false,
        reason: "terminal",
        status: entry.status,
      };
    }

    entry.deferredRefunds.push(amountKobo);

    return {
      applied: false,
      reason: "deferred",
      status: entry.status,
    };
  }

  function get(reference) {
    const entry = entries.get(reference);

    if (!entry) {
      return undefined;
    }

    return {
      reference: entry.reference,
      status: entry.status,
      amountKobo: entry.amountKobo,
      refundedKobo: entry.refundedKobo,
    };
  }

  return { handle, get };
}
